-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-the-hyde-park-demo-report', 'bf-the-hyde-park-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-the-hyde-park-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 55, "representedLightCount": 1600, "extrapolationFactor": 29.090909, "preInstallBaseline": 28.66, "postInstallAverage": 12.53, "savedKwhPerDay": 16.13, "benchmarkSavingsPct": 64.47, "projectedSavedKwhPerDay": 537.5157, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2025-06-07'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-the-hyde-park-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-the-hyde-park-offer', 'bf-the-hyde-park-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-the-hyde-park-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 55, "representedLightCount": 1600, "benchmarkSavingsPct": 64.47, "preInstallBaseline": 28.66, "projectedSavedKwhPerDay": 18.4771}]'::jsonb,
       10, 65.6168, 6.90, 36,
       32500.00, '2025-06-07'::date, a.id,
       '2025-06-07'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'The Hyde Park'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-the-hyde-park-agreement', 'bf-the-hyde-park-pipe', 'bf-the-hyde-park-offer', '2025-06-07'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2025-06-07'::date, '2025-06-07'::date,
       '2025-06-07'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-theoretical, fee-flat-monthly-charge, report-share-differs-from-agreement, proration-on-a-30-day-month. SOURCE IS THE USER''S PASTED TEXT for the agreement and demo report; the first invoice is a real file. Every figure reconciles: 1,600 x 20W x 24h x 30 = 23,040 kWh/month, less a stated 9,341 post-installation, gives 13,699 kWh saved at Rs 6.90 = Rs 94,523, less the flat Rs 32,500 charge = Rs 62,023 retained, all as printed. FEE IS A FLAT Rs 32,500/month, not a share; the 65.6168/34.3832 split recorded is what that amount works out to. The agreement calls it ''approximately 35% + charges of Inverter lights & installation''; the demo report''s own ''40% of these verified savings'' matches neither. 1,600 lights agreed and 1,600 installed, but they are NOT one kind of fitting: 1,475 motion-sensor dimmable and 125 inverter tube lights that stay on at full brightness for emergency lighting. The demo covered motion-sensor lights only, so it does not represent all 1,600 equally. Billing from 6 Jul 2025: the first invoice covers 26 days of July, and it prorates on a THIRTY-day month - Rs 32,500/30 = Rs 1,083.33/day x 26 = Rs 28,166.58 - not on July''s actual 31. So installation finished on or before 5 Jul 2025. Agreement notarised and signed 07 Jun 2025; its own effective date is 01 Jul 2025.',
       'Documents/The_Hyde_Park/2025-06/Agreements/The_Hyde_Park_Agreement_2025-06-07.pdf',
       'The_Hyde_Park_Agreement_2025-06-07.pdf',
       -- The scan reaches us the day after signing.
       ('2025-06-07'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

